item.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const pkg = JSON.parse(readFileSync('package.json','utf8'));
const sections = ['dependencies','peerDependencies','devDependencies'];
const rows = [];
for (const section of sections) {
  for (const [name, current] of Object.entries(pkg[section] || {})) {
    let latest = '';
    try { latest = execFileSync('npm', ['view', name, 'version'], { encoding:'utf8', stdio:['ignore','pipe','pipe'] }).trim(); }
    catch (e) { latest = "'`ERROR: ${e.stderr?.toString()?.trim() || e.message}`; }
    rows.push({ section, name, current, latest });
  }
}
console.log(JSON.stringify(rows, null, 2));
NODE'

